        "text": "Свод правил СП 158.13330.2014 уделяет особое внимание принципам функционального зонирования, которые позволяют эффективно разделить различные по своему назначению пространства и предотвратить перекрестное загрязнение. Медицинские учреждения делятся на чистые, условно-чистые и грязные зоны, а также зоны повышенного эпидемиологического риска. Например, операционные блоки, реанимационные отделения, стерилизационные относятся к чистым зонам, требующим особых инженерных решений по вентиляции и кондиционированию. Приемные отделения, диагностические кабинеты, палаты относятся к условно-чистым. Санитарные узлы, помещения для сбора отходов – грязные зоны. Отделения инфекционных заболеваний или фтизиатрии имеют свои специфические требования к изолированности. Грамотно разработанное зонирование является фундаментом для обеспечения санитарно-эпидемиологической безопасности и лежит в основе успешного получения разрешительной документации."
