        "text": "Санитарно-эпидемиологическое заключение (СЭЗ) — это официальный документ, выдаваемый Роспотребнадзором, который удостоверяет соответствие зданий, сооружений, помещений, оборудования и иной продукции, используемой для осуществления медицинской деятельности, государственным санитарно-эпидемиологическим правилам и нормативам. Без наличия СЭЗ невозможно получить медицинскую лицензию и, соответственно, начать легальную деятельность. Выдача заключения основана на экспертном заключении, которое формируется по результатам санитарно-эпидемиологической экспертизы. Эта экспертиза включает в себя проверку документации, инструментальные измерения (анализы воды, воздуха, замеры уровня шума, освещенности, радиационного фона) и осмотр объекта. Мы, как проектная организация, на этапе проектирования закладываем все необходимые решения, чтобы объект соответствовал этим нормам и ускорил процесс получения СЭЗ. Важно понимать, что каждое медицинское учреждение, будь то стоматология, многопрофильный медицинский центр или диагностическая лаборатория, обязано получить СЭЗ на каждый вид деятельности и каждое отдельно расположенное помещение."
