        "text": "Проектирование медицинского объекта – это не просто набор чертежей. Это создание условий для спасения жизней и поддержания здоровья, где каждая деталь должна быть продумана с учетом строжайших норм и требований к комфорту и безопасности. В пластической хирургии это приобретает особое значение, ведь мы работаем со здоровьем и мечтами людей.",
