    "lead": "Проектирование операционного блока является одним из наиболее ответственных и сложных этапов создания медицинского учреждения. Его функциональность, безопасность и соответствие строгим санитарно-эпидемиологическим нормам напрямую влияют на качество медицинской помощи и безопасность пациентов и персонала. В данной статье мы подробно рассмотрим состав помещений операционного блока, минимально необходимые площади, а также ключевые инженерные требования, регламентируемые актуальными нормативными документами, такими как СанПиН 2.1.3678-20 и СП 158.13330.2014.",
