        "type": "p",
        "text": "Особое внимание в операционных блоках уделяется параметрам микроклимата и качеству воздуха. Температура воздуха в операционных должна поддерживаться в пределах +21…+24 °C, относительная влажность — 50-60%. Кратность воздухообмена является одним из ключевых показателей. Согласно СанПиН 2.1.3678-20, в операционных необходимо обеспечивать не менее чем 10-кратный воздухообмен в час с использованием приточно-вытяжной вентиляции с механическим побуждением. При этом приток должен преобладать над вытяжкой, создавая избыточное давление, которое предотвращает проникновение неочищенного воздуха из смежных помещений. Для операционных зон класса А и Б обязательна установка систем обеззараживания воздуха, например, HEPA-фильтров, обеспечивающих высокую степень очистки."
