        "type": "p",
        "text": "После завершения проектирования и строительства, крайне важным этапом является получение санитарно-эпидемиологического заключения (СЭЗ) и медицинской лицензии. Наша компания осуществляет полное сопровождение этого процесса. Мы готовим всю необходимую документацию, оказываем консультационную поддержку и взаимодействуем с контролирующими органами. Срок получения СЭЗ обычно составляет 20-25 рабочих дней, а медицинской лицензии – до 15 рабочих дней после предоставления полного пакета документов и получения СЭЗ. Мы гарантируем, что разработанная проектная документация будет полностью соответствовать требованиям для успешного прохождения всех этапов лицензирования, минимизируя риски задержек и отказов."
