        "type": "p",
        "text": "Система вентиляции в дневном стационаре играет ключевую роль в поддержании санитарно-гигиенического режима, особенно в условиях, где проводятся инвазивные процедуры или реабилитационные мероприятия после хирургического вмешательства. Согласно СанПиН 2.1.3678-20, в медицинских организациях должна быть предусмотрена приточно-вытяжная вентиляция с механическим побуждением. Воздух подается в палаты сверху, выводится снизу, чтобы обеспечить максимально эффективный воздухообмен и вытеснение загрязненного воздуха. Для помещений, где выполняются чистые манипуляции (процедурные, предоперационные), кратность воздухообмена должна быть выше, а приточный воздух — проходить многоступенчатую очистку с использованием фильтров высокой эффективности (HEPA). Это минимизирует риск распространения аэрозольных инфекций и обеспечивает стерильность воздушной среды. Особое внимание уделяется отсутствию рециркуляции воздуха между различными функциональными зонами, чтобы исключить перекрестное загрязнение. Также необходимо предусмотреть возможность локальной очистки воздуха с использованием бактерицидных облучателей, особенно в периоды подъема заболеваемости ОРВИ и гриппом. Проектные решения должны гарантировать не только соответствие кратности воздухообмена, но и правильное направление воздушных потоков – из более чистых помещений в менее чистые."
