        "type": "p",
        "text": "Организация санузлов в дневном стационаре требует соблюдения не только общих санитарных норм, но и специфических требований для медицинских учреждений. В составе дневного стационара обязательно должны быть предусмотрены отдельные санузлы для пациентов и персонала. Санузлы для пациентов должны быть оборудованы унитазами, раковинами, а также, при необходимости, душевыми кабинами. Важным аспектом является обеспечение доступности для маломобильных групп населения, что означает расширенные дверные проемы, поручни, специализированное сантехническое оборудование. Наличие достаточного количества санузлов позволяет избежать очередей и обеспечить высокий уровень гигиены. Для персонала должны быть предусмотрены отдельные санузлы, оснащенные всеми необходимыми элементами, включая умывальники с локтевыми смесителями и дозаторами антисептиков. Внутренняя инфраструктура также включает в себя помещения для хранения уборочного инвентаря, приготовления дезинфицирующих растворов, помещения для чистого и грязного белья. Все инженерные сети — водоснабжение, канализация, электричество — должны быть выполнены в соответствии с действующими СНиП и ГОСТ, исключая аварийные ситуации и обеспечивая бесперебойную работу учреждения."
