    "lead": "Проектирование кабинета магнитно-резонансной томографии (МРТ) относится к одним из наиболее сложных разделов при создании медицинского объекта. Основные трудности связаны с необходимостью обеспечения электромагнитной совместимости оборудования, учета значительных массогабаритных характеристик томографа, точного расчета тепловыделения и организации специализированных путей доставки. Отступление от нормативов и рекомендаций производителя оборудования на этапе проектирования неизбежно приведет к проблемам в эксплуатации и, возможно, к полному невозможности использования МРТ-аппарата. Наша задача как проектной организации — обеспечить полное соответствие всем требованиям для безопасной и эффективной работы кабинета МРТ.",
