        "text": "Проектирование комплекса помещений для МРТ состоит из нескольких функциональных зон, включая аппаратную (процедурную), пультовую, технические помещения и, при необходимости, комнату подготовки пациента, зону переодевания и санузел. Важно обеспечить зонирование с учетом магнитных полей и минимизации влияния внешних источников помех. Общая площадь аппаратной должна быть достаточной для размещения томографа, соблюдения необходимых санитарных разрывов и удобства перемещения персонала и пациента на каталке. Стандартная площадь аппаратной для МРТ, как правило, составляет от 25 м² до 40 м², в зависимости от модели аппарата и требуемой индукции магнитного поля. При проектировании мы ориентируемся на минимальные 27 м² для аппаратов 1.5 Тл и более 35 м² для 3.0 Тл, что обеспечивает комфорт и безопасность."
