        "text": "Работа МРТ-аппарата сопровождается значительным тепловыделением, и поддержание стабильной температуры является ключевым фактором для его корректного функционирования и долговечности. Помимо общеобменной вентиляции, в кабинете МРТ-томографа необходимо предусмотреть автономную систему кондиционирования, обеспечивающую поддержание заданных производителем температурных параметров — как правило, в диапазоне от +18 °C до +24 °C, с влажностью от 40% до 60%. Тепловыделение самого аппарата может достигать до 20 кВт, не считая теплопритоков от других источников (персонал, освещение, солнечная радиация). Часто для охлаждения магнита используется криогенная система на основе жидкого гелия, а также система водяного охлаждения градиентных катушек. Соответственно, архитектурное решение должно предусматривать пути прокладки воздуховодов, фреонопроводов или труб системы чиллер-фанкойл, а также место для размещения внешних блоков кондиционеров, чиллеров и криокомпрессоров. Учитывается также возможность так называемого «квенча» — аварийного сброса паров гелия, для чего необходима специальная вытяжная шахта диаметром не менее 200 мм с выходом на крышу здания в безопасной зоне, высота которой определяется по аэродинамическим расчетам (СП 60.13330.2020)."
