        "text": "Минимальная площадь кабинета УЗИ регламентирована нормативными документами и зависит от его функционального назначения. Для стандартного кабинета ультразвуковой диагностики с одним аппаратом требуется не менее 12 м². Если кабинет предполагается использовать для проведения инвазивных процедур под контролем УЗИ, что требует дополнительного оборудования и стерильного поля, а также расширенного штата медицинского персонала, площадь должна быть увеличена. Важно учитывать, что кабинет должен обеспечивать свободный доступ к пациенту со всех сторон для проведения исследования и возможность эвакуации, а также комфортное размещение медицинского оборудования и мебели. Геометрические параметры помещения должны способствовать эффективному зонированию, разделяя зоны ожидания, подготовки и непосредственно исследования, при этом соблюдая эргономику рабочего процесса."
