        "type": "p",
        "text": "Кабинет УЗИ должен быть обеспечен как естественным, так и искусственным освещением. Естественное освещение, как правило, обеспечивается окном. Однако в процессе проведения исследования предпочтительно приглушенное освещение для лучшей визуализации изображения на мониторе. Поэтому на окнах должны быть предусмотрены жалюзи или плотные шторы. Искусственное освещение должно быть регулируемым, с возможностью локального освещения рабочей зоны. Ориентировочные значения освещенности: общее освещение 200–300 лк, локальное — до 500 лк. Важно избегать бликов на мониторе аппарата. Системы отопления, вентиляции и кондиционирования должны обеспечивать оптимальный микроклимат: температуру воздуха в пределах +20–22 °C, относительную влажность 40–60%. Кратность воздухообмена, как правило, составляет 2-3 приток и 3-4 вытяжка, в зависимости от объема помещения и наличия специфического оборудования. Это необходимо для поддержания комфортных условий и удаления возможных вредных веществ."
