        "text": "Отделка кабинетов физиотерапии должна соответствовать общим санитарно-гигиеническим требованиям для медицинских учреждений, изложенным в СанПиН 2.1.3678-20 и СП 158.13330.2014. Это означает, что все поверхности должны быть гладкими, без дефектов, допускающими влажную уборку и дезинфекцию. Для стен предпочтительны моющиеся обои, окраска высококачественными водоэмульсионными красками, облицовка керамической плиткой или панелями из материалов, устойчивых к агрессивным средам. При использовании электро- и магнитотерапии важно учитывать совместимость отделочных материалов с возможным экранированием. Полы должны быть выполнены из износостойких, антистатических материалов, легко очищаемых и не впитывающих влагу, например, негорючий линолеум, наливные полы или керамическая плитка с антискользящей поверхностью. Потолки также должны быть гладкими, допускающими влажную уборку, с возможностью дезинфекции, предпочтительны подвесные потолки из влагостойких материалов."
