        "type": "p",
        "text": "Планировка гинекологического кабинета должна отвечать строгим функциональным и санитарным требованиям. Согласно СанПиН 2.1.3678-20, кабинет должен состоять как минимум из двух помещений: смотровой и кабинета врача. При этом допускается совмещение, но с обязательным наличием ширмы или перегородки, отделяющей зону осмотра. Важно обеспечить достаточные площади для свободного размещения оборудования и удобства перемещения персонала и пациентов. Минимальная площадь смотровой зоны не должна быть менее 12 м², а кабинета врача – от 10 м², если это отдельные помещения. В случае совмещения, общая площадь должна быть не менее 18 м². Также необходимо предусмотреть место для хранения инструментария и стерильных материалов, а также зону для обработки и дезинфекции инструментов, если таковая не предусмотрена централизованно. Отдельное внимание уделяется ориентации окон и качеству естественного освещения, которые должны соответствовать нормам."
