        "text": "Одним из наиболее критичных аспектов проектирования детской клиники является эффективная изоляция потоков пациентов. Это необходимо для предотвращения распространения инфекций, особенно между больными и здоровыми детьми. Согласно действующим нормативам, должны быть предусмотрены различные зоны и маршруты движения. В идеале, должны быть отдельные входы, гардеробные и зоны ожидания для здоровых детей (например, для профилактических осмотров и вакцинации) и для детей с симптомами заболеваний. Этот принцип реализуется через создание чёткого зонирования пространства, часто с использованием физических барьеров или различных этажей/секций. В случае стационарных отделений, изоляция распространяется и на палаты, особенно инфекционные, где требуется наличие шлюзов и отдельных систем вентиляции. Мы всегда закладываем решения, которые минимизируют перекрёстное заражение, что критически важно для получения положительного заключения Роспотребнадзора."
