        "type": "p",
        "text": "Потолки в медицинских учреждениях должны быть гладкими, без щелей, легкодоступными для влажной уборки и дезинфекции. Они не должны выделять вредных веществ и быть негорючими. В большинстве помещений применяются окрашенные потолки из гипсокартона или штукатурки водоэмульсионными красками, имеющими санэпидзаключение. В чистых помещениях, как правило, устанавливаются подвесные потолки со скрытой системой крепления или цельнотянутые натяжные потолки из материалов, соответствующих требованиям по классу чистоты ISO 5-7. В помещениях с высокими требованиями к акустике или с необходимостью частого доступа к инженерным коммуникациям могут использоваться кассетные или реечные потолки из металлических панелей со специальным гигиеническим покрытием. При этом важно, чтобы все стыки и соединения были герметичны, а конструкция потолка исключала возможность скапливания пыли и конденсата. Выбор потолочной системы также зависит от наличия встроенного оборудования, такого как вентиляционные решетки, светильники, системы пожаротушения. Наши проекты предусматривают только сертифицированные системы, срок службы которых гарантирует надежность и безопасность на протяжении всего эксплуатационного периода объекта."
