    "lead": "Качественное освещение в медицинских кабинетах является одним из ключевых факторов, влияющих на точность диагностики, эффективность лечения и комфорт как медицинского персонала, так и пациентов. При проектировании медицинских объектов необходимо строго соблюдать действующие нормативные требования к уровню освещённости, коэффициенту естественной освещённости (КЕО), а также качеству и безопасности световой среды. Проектное бюро «МедПроект» специализируется на разработке проектной документации для медицинских учреждений с учётом всех этих аспектов, обеспечивая соответствие объектов критериям комфорт+, что напрямую влияет на качество последующей эксплуатации.",
