        "text": "Освещение в медицинских учреждениях регламентируется целым рядом нормативных документов. Основными из них являются СанПиН 2.1.3678-20 «Санитарно-эпидемиологические требования к эксплуатации помещений, зданий, сооружений, оборудования и транспорта, а также условиям деятельности хозяйствующих субъектов, осуществляющих продажу товаров, выполнение работ или оказание услуг», СП 158.13330.2014 «Здания и помещения медицинских организаций. Правила проектирования» и ГОСТ Р 52539-2006 «Чистота воздуха в лечебных учреждениях. Общие требования». Эти документы устанавливают требования как к естественному, так и к искусственному освещению, определяя минимальные допустимые параметры для различных функциональных зон медицинских объектов."
