        "text": "Проектирование путей эвакуации в медицинском учреждении является одной из наиболее критичных задач, поскольку ошибки могут стоить жизни. Эвакуационные пути должны быть свободны, освещены и четко обозначены. Ширина коридоров, предназначенных для эвакуации, должна быть не менее 1,2 м, а для палат — не менее 1,6 м, обеспечивая возможность беспрепятственного перемещения носилок и инвалидных колясок. Дверные проемы на путях эвакуации должны быть не уже 0,8 м. Особое внимание уделяется лестничным клеткам: они должны быть незадымляемыми и иметь прямой выход наружу или на путь эвакуации, ведущий наружу. Количество эвакуационных выходов из каждого помещения, этажа и здания должно определяться расчетом, но не может быть менее двух. В медицинских учреждениях с постоянным пребыванием 50 и более человек, а также для операционных и реанимационных блоков, необходима установка систем противодымной защиты и подпора воздуха на путях эвакуации, чтобы обеспечить незадымляемость. Проектирование учитывает скорость движения людей в зависимости от их физического состояния."
