        "type": "p",
        "text": "Процесс проектирования медицинского учреждения, как правило, делится на несколько стадий, каждая из которых имеет свою стоимость и объем работ. Первая стадия – это Эскизный проект (ЭП), который включает первичную концепцию, планировочные решения, общую объемно-планировочную структуру. Это приблизительно 10-15% от общей стоимости проектирования. Далее следует стадия Проектной документации (П), которая является основой для прохождения государственной или негосударственной экспертизы. Здесь разрабатываются основные разделы проекта: архитектурные, конструктивные, инженерные, технологические решения, сметы. Эта стадия занимает около 40-50% от общей стоимости. Самая детальная и объемная стадия – Рабочая документация (РД), которая содержит все необходимые чертежи и спецификации для строительно-монтажных работ. Стоимость РД составляет 35-45% от общего бюджета. Важно отметить, что полный цикл проектирования, включающий все три стадии, является наиболее предпочтительным для обеспечения высокого качества и соответствия всем нормативным требованиям, что в итоге минимизирует риски при строительстве и эксплуатации объекта."
