        "type": "p",
        "text": "В техническом задании также могут быть оговорены желаемые сроки выполнения проектных работ и предварительная оценка бюджета. Следует понимать, что сроки напрямую зависят от площади объекта и сложности проекта. Например, для объекта площадью 500-1000 м² разработка полноценного проекта занимает от 2 до 4 месяцев. Прохождение государственной или негосударственной экспертизы проекта – еще порядка 30 – 45 календарных дней. Отдельно стоит отметить сроки получения разрешительной документации: санитарно-эпидемиологическое заключение (СЭЗ) Роспотребнадзора обычно оформляется в течение 20-25 рабочих дней, а медицинская лицензия – до 15 рабочих дней после предоставления полного пакета документов. Общая стоимость проектирования для клиники площадью от 400 м² может варьироваться от 1500 до 3500 рублей за квадратный метр в зависимости от сложности и детализации проекта. В «МедПроекте» мы всегда стараемся максимально точно рассчитать эти параметры на основе детализированного ТЗ, чтобы наши клиенты имели четкое представление о финансовых и временных затратах. Наши услуги не включают строительство, но мы обеспечиваем полное сопровождение проекта до получения СЭЗ и медицинской лицензии."
